on conflict (slug) do update set
  name = excluded.name,
  aliases = excluded.aliases,
  abbrev = excluded.abbrev,
  specialty = excluded.specialty,
  score_ids = excluded.score_ids,
  lab_ids = excluded.lab_ids,
  guideline_kw = excluded.guideline_kw,
  body = excluded.body,
  status = excluded.status,
  is_stub = false;

-- A korábbi, eltérő megnevezésű besorolások egységesítése.
update public.diseases set specialty = 'Bőrgyógyászat és sebellátás'
where specialty in ('Sebészet / sebkezelés', 'Sebkezelés', 'Bőrgyógyászat',
                    'Dermatológia', 'Bőrgyógyászat-sebellátás');

-- A régi azonosítójú diabéteszes láb adatlap lezárása, ha külön létezik.
update public.diseases set status = 'expired',
  name = name || ' — felváltotta: Diabéteszes láb'
where slug = 'diabeteses_lab' and status <> 'expired'
  and exists (select 1 from public.diseases d where d.slug = 'diabeteses-lab');

-- ══ Ellenőrzés ═══════════════════════════════════════════
-- Nyolc kidolgozott kórképnek kell megjelennie.
select slug, name,
  case when body ->> 'brief_what' is null then 'csonk' else 'kidolgozott' end as allapot,
  body ->> 'version' as forras_ev
from public.diseases
where specialty = 'Bőrgyógyászat és sebellátás' and status = 'published'
order by name;
